def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    nr, nc = len(row_ranges), len(col_ranges)
    patterns = {}
    for i, (r0, r1) in enumerate(row_ranges):
        for j, (c0, c1) in enumerate(col_ranges):
            for color in set(v for row in grid[r0:r1] for v in row[c0:c1] if v != 0):
                patterns[i, j, color] = {
                    (r - r0, c - c0)
                    for r in range(r0, r1)
                    for c in range(c0, c1)
                    if grid[r][c] == color
                }

    for i in range(nr - 1):
        for j in range(nc - 1):
            dims = [row_ranges[i][1] - row_ranges[i][0],
                    row_ranges[i + 1][1] - row_ranges[i + 1][0],
                    col_ranges[j][1] - col_ranges[j][0],
                    col_ranges[j + 1][1] - col_ranges[j + 1][0]]
            if len(set(dims)) != 1:
                continue
            bh, bw = dims[0], dims[2]
            colors = {key[2] for key in patterns
                      if key[0] in (i, i + 1) and key[1] in (j, j + 1)}
            for color in colors:
                cells = [(i, j), (i, j + 1), (i + 1, j), (i + 1, j + 1)]
                existing = [patterns.get((a, b, color), set()) for a, b in cells]
                if sum(bool(p) for p in existing) != 3:
                    continue

                # Convert each occupied pattern to the common, unreflected orientation.
                canonical = []
                for (a, b), pat in zip(cells, existing):
                    if not pat:
                        continue
                    canonical.append({
                        (bh - 1 - r if a == i + 1 else r,
                         bw - 1 - c if b == j + 1 else c)
                        for r, c in pat
                    })
                if not all(p == canonical[0] for p in canonical[1:]):
                    continue

                missing = next(k for k, p in enumerate(existing) if not p)
                a, b = cells[missing]
                pat = {
                    (bh - 1 - r if a == i + 1 else r,
                     bw - 1 - c if b == j + 1 else c)
                    for r, c in canonical[0]
                }
                r0, _ = row_ranges[a]
                c0, _ = col_ranges[b]
                for r, c in pat:
                    out[r0 + r][c0 + c] = color

    return out
